if (.Platform$OS.type == 'windows') Sys.setlocale('LC_CTYPE','English_United States.utf8')
library(sf);library(readr)
p <- 'visuals/2026-11-switzerland-housing-vacancy'; gp <- Sys.getenv('SWISSTOPO_2026_GPKG'); if (!nzchar(gp) || !file.exists(gp)) stop('Set SWISSTOPO_2026_GPKG to the January 2026 swisstopo GeoPackage')
g <- st_read(gp,'tlm_bezirksgebiet',quiet=TRUE); k <- st_read(gp,'tlm_kantonsgebiet',quiet=TRUE)
x <- read_csv(file.path(p,'data/fso-district-rates-2026.csv'),show_col_types=FALSE); x <- x[grepl('^B_',x$GR_KT_GDE),]; x$id <- as.integer(sub('B_','',x$GR_KT_GDE))
extras <- x[!x$id %in% g$bezirksnummer,]; print(extras[,c('id','OBS_VALUE')]); print(names(k));print(st_drop_geometry(k)[1,c('kantonsnummer','name')])
cats <- extras$id %/% 100; stopifnot(all(cats %in% k$kantonsnummer),all(extras$id %% 100 == 0)); missing <- k[match(cats,k$kantonsnummer),]; new <- data.frame(id=c(g$bezirksnummer, extras$id),district=c(g$name,paste0(missing$name,' (canton)')),canton_id=c(g$kantonsnummer,missing$kantonsnummer),type=c(rep('district',nrow(g)),rep('canton equivalent',nrow(missing))))
geom <- st_sfc(c(st_geometry(st_zm(g)),st_geometry(st_zm(missing))),crs=st_crs(g)); sfobj<-st_sf(new,geometry=geom); sfobj<-st_simplify(sfobj,dTolerance=40,preserveTopology=TRUE); stopifnot(nrow(sfobj)==144,!anyDuplicated(sfobj$id),setequal(sfobj$id,x$id))
values<-x[match(sfobj$id,x$id),]; dat<-data.frame(year=2026,district_id=sfobj$id,district=sfobj$district,canton_id=sfobj$canton_id,geography_type=sfobj$type,vacancy_rate_pct=values$OBS_VALUE,status=values$OBS_STATUS); dat$canton_code <- c('ZH','BE','LU','UR','SZ','OW','NW','GL','ZG','FR','SO','BS','BL','SH','AR','AI','SG','GR','AG','TG','TI','VD','VS','NE','GE','JU')[dat$canton_id]; print(dat[order(dat$vacancy_rate_pct),][c(1:3,142:144),]);cat('below=',sum(dat$vacancy_rate_pct<.93),' equal=',sum(dat$vacancy_rate_pct==.93),' above=',sum(dat$vacancy_rate_pct>.93),'\n');print(table(dat$status))
st_write(sfobj,file.path(p,'data/swisstopo-districts-2026.gpkg'),layer='districts',quiet=TRUE,delete_dsn=TRUE);write_csv(dat,file.path(p,'data/district-vacancy-rate-2026.csv'))
